func (m *Metrics) healthCheck() error {
	m.lifecycleMu.Lock()
	defer m.lifecycleMu.Unlock()

	// A composed production instance observes the Manager-owned diagnostic
	// server; a standalone instance retains its direct server ownership.
	if m.managerClaimed {
		if !m.managerHealthy {
			return fmt.Errorf("manager-owned metrics server not running")
		}
		return nil
	}
	if m.server == nil {
		return fmt.Errorf("metrics server not running")
	}

	// Could add HTTP health check here if needed
	return nil
}

func startPProf(debug bool, port int, server *http.Server, listen func(string, string) (net.Listener, error)) <-chan struct{} {
	done := make(chan struct{})
	if !debug || port <= 0 {
		close(done)
		return done
	}
	go func() {
		defer close(done)
		addr := fmt.Sprintf(":%d", port)
		// stdout because this runs before slog is configured (pre-Phase-A).
		fmt.Printf("Starting pprof server on %s\n", addr)
		listener, err := listen("tcp", addr)
		if err == nil {
			err = server.Serve(listener)
		}
		if err != nil && err != http.ErrServerClosed {
			fmt.Printf("pprof server error: %v\n", err)
		}
	}()
	return done
}

