func RegisterAll(registry *Registry) error {
	services := map[string]Constructor{
		"metrics":           NewMetrics,
		"message-logger":    NewMessageLoggerService,
		"log-forwarder":     NewLogForwarderService,
		"metrics-forwarder": NewMetricsForwarderService,
		"component-manager": NewComponentManager,
		"heartbeat":         NewHeartbeatService,
		// Account storage observability. Opt-in and report-only: a deployment
		// that does not name it in its `services` block never constructs it.
		StorageObservabilityServiceName: NewStorageObservabilityService,
	}

	for name, constructor := range services {
		if err := registry.Register(name, constructor); err != nil {
			return fmt.Errorf("register %s: %w", name, err)
		}
	}
	return nil
}

func SchemaFromType(t reflect.Type) map[string]any {
	// Handle pointers - use JSON Schema Draft-07 anyOf pattern for nullable
	if t.Kind() == reflect.Pointer {
		elemSchema := SchemaFromType(t.Elem())
		return map[string]any{
			"anyOf": []any{
				elemSchema,
				map[string]any{"type": "null"},
			},
		}
	}

	switch t.Kind() {
	case reflect.String:
		return map[string]any{"type": "string"}

	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return map[string]any{"type": "integer"}

	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return map[string]any{"type": "integer", "minimum": 0}

	case reflect.Float32, reflect.Float64:
		return map[string]any{"type": "number"}

	case reflect.Bool:
		return map[string]any{"type": "boolean"}

	case reflect.Struct:
		// Special case: time.Time
		if t == reflect.TypeOf(time.Time{}) {
			return map[string]any{"type": "string", "format": "date-time"}
		}
		return schemaFromStruct(t)

	case reflect.Slice:
		// Special case: []byte
		if t.Elem().Kind() == reflect.Uint8 {
			return map[string]any{"type": "string", "format": "byte"}
		}
		return map[string]any{
			"type":  "array",
			"items": SchemaFromType(t.Elem()),
		}

	case reflect.Map:
		return map[string]any{
			"type":                 "object",
			"additionalProperties": SchemaFromType(t.Elem()),
		}

	case reflect.Interface:
		// interface{} / any - allow anything
		return map[string]any{}

	default:
		// Fallback for unknown types
		return map[string]any{"type": "string"}
	}
}

func (ml *MessageLogger) createKVWatcher(
	ctx context.Context,
	kv jetstream.KeyValue,
	bucket, pattern string,
) (chan *KVWatchEvent, jetstream.KeyWatcher, error) {
	// Use WatchAll if pattern is "*" or empty, otherwise Watch with pattern
	var watcher jetstream.KeyWatcher
	var err error

	if pattern == "" || pattern == "*" {
		watcher, err = kv.WatchAll(ctx)
	} else {
		watcher, err = kv.Watch(ctx, pattern)
	}

	if err != nil {
		return nil, nil, fmt.Errorf("failed to create KV watcher: %w", err)
	}

	// Buffer size for events
	bufferSize := 100
	eventChan := make(chan *KVWatchEvent, bufferSize)

	// Start goroutine to consume watcher updates
	go ml.consumeKVWatchUpdates(ctx, watcher, bucket, eventChan)

	return eventChan, watcher, nil
}

func NewHeartbeatService(rawConfig json.RawMessage, deps *Dependencies) (Service, error) {
	// Parse config
	var cfg HeartbeatConfig
	if len(rawConfig) > 0 {
		if err := json.Unmarshal(rawConfig, &cfg); err != nil {
			return nil, fmt.Errorf("parse heartbeat config: %w", err)
		}
	}

	// Apply defaults
	if cfg.Interval == "" {
		cfg.Interval = "30s"
	}

	// Validate configuration
	if err := cfg.Validate(); err != nil {
		return nil, fmt.Errorf("validate heartbeat config: %w", err)
	}

	// Parse interval
	interval, err := time.ParseDuration(cfg.Interval)
	if err != nil {
		return nil, fmt.Errorf("invalid interval: %w", err)
	}

	// Create base service with options
	var opts []Option
	if deps != nil && deps.Logger != nil {
		opts = append(opts, WithLogger(deps.Logger))
	}

	baseService := NewBaseServiceWithOptions("heartbeat", nil, opts...)

	hb := &HeartbeatService{
		BaseService: baseService,
		config:      cfg,
		interval:    interval,
		stopChan:    make(chan struct{}),
		logger:      slog.Default().With("source", "heartbeat"),
	}

	if deps != nil {
		hb.serviceManager = deps.ServiceManager
	}

	return hb, nil
}

