func (m *Metrics) Start(ctx context.Context) error {
	if err := validateLifecycleContext(ctx, "Metrics", "Start"); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return errs.WrapInvalid(err, "Metrics", "Start", "context already ended")
	}
	m.lifecycleMu.Lock()
	if m.used {
		m.lifecycleMu.Unlock()
		return errs.WrapFatal(errs.ErrAlreadyStarted, "Metrics", "Start", "service instance already used")
	}
	runCtx, cancel := context.WithCancel(ctx)
	startDone := make(chan struct{})
	m.used = true
	m.cleanupPending = true
	m.startDone = startDone
	m.cancel = cancel
	managerClaimed := m.managerClaimed
	m.lifecycleMu.Unlock()

	if !managerClaimed {
		server := metric.NewServer(m.config.Port, m.config.Path, m.registry, m.security)
		slog.Info("Starting metrics server", "port", m.config.Port, "path", m.config.Path)
		if err := m.startServer(runCtx, server); err != nil {
			cancel()
			m.lifecycleMu.Lock()
			m.cleanupPending = false
			m.terminal = true
			m.cancel = nil
			close(startDone)
			m.startDone = nil
			m.lifecycleMu.Unlock()
			return fmt.Errorf("start metrics server: %w", err)
		}
		m.lifecycleMu.Lock()
		m.server = server
		m.lifecycleMu.Unlock()
		if m.testServerPublished != nil {
			close(m.testServerPublished)
			<-m.testStartRelease
		}
	}

	// The listener is owned before BaseService publishes running state. A base
	// failure therefore retains the exact provider handle for bounded rollback.
	if err := m.BaseService.Start(runCtx); err != nil {
		rollbackErr := lifecyclecleanup.RollbackFailedStart(ctx, m.cleanupFailedStart)
		m.lifecycleMu.Lock()
		if rollbackErr == nil {
			m.server = nil
			m.cancel = nil
			m.cleanupPending = false
			m.terminal = true
		}
		close(startDone)
		m.startDone = nil
		m.lifecycleMu.Unlock()
		return errors.Join(fmt.Errorf("start metrics base service: %w", err), rollbackErr)
	}
	m.lifecycleMu.Lock()
	m.running = true
	m.cleanupPending = false
	close(startDone)
	m.startDone = nil
	m.lifecycleMu.Unlock()
	scheme := "http"
	if m.security.TLS.Server.Enabled {
		scheme = "https"
	}
	slog.Info(
		"Metrics service started successfully",
		"url",
		fmt.Sprintf("%s://localhost:%d%s", scheme, m.config.Port, m.config.Path),
	)

	return nil
}

func (s *MilestoneService) Start(ctx context.Context) error {
	if err := validateLifecycleContext(ctx, "MilestoneService", "Start"); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return semerrs.WrapInvalid(err, "MilestoneService", "Start", "context already ended")
	}
	s.mu.Lock()
	if s.used {
		s.mu.Unlock()
		return semerrs.WrapFatal(semerrs.ErrAlreadyStarted,
			"MilestoneService", "Start", "service instance already used")
	}
	s.used = true
	s.startDone = make(chan struct{})
	startDone := s.startDone
	s.mu.Unlock()
	defer close(startDone)

	if err := s.BaseService.Start(ctx); err != nil {
		s.mu.Lock()
		s.terminal = true
		s.mu.Unlock()
		return err
	}
	stop, err := s.subscriber.Start(ctx, s.client, s.cfg)
	s.mu.Lock()
	if stop != nil {
		s.stop = stop
	}
	if err == nil {
		s.running = true
		s.mu.Unlock()
		return nil
	}
	s.cleanupPending = stop != nil
	s.mu.Unlock()

	rollbackErr := lifecyclecleanup.RollbackFailedStart(ctx, func(cleanupCtx context.Context) error {
		var subscriberErr error
		if stop != nil {
			subscriberErr = stop(cleanupCtx)
		}
		return errors.Join(subscriberErr, s.BaseService.Stop(cleanupCtx))
	})
	s.mu.Lock()
	if rollbackErr == nil {
		s.stop = nil
		s.cleanupPending = false
		s.terminal = true
	} else {
		s.cleanupPending = true
	}
	s.mu.Unlock()
	return errors.Join(fmt.Errorf("milestone subscriber start: %w", err), rollbackErr)
}

