func (r *streamOverrideExpiryReporter) run(ctx context.Context) {
	ticker := time.NewTicker(overrideExpiryCheckInterval)
	defer ticker.Stop()

	r.evaluate(time.Now())
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			r.evaluate(time.Now())
		}
	}
}

func detectKVOperation(entry jetstream.KeyValueEntry) string {
	switch entry.Operation() {
	case jetstream.KeyValuePut:
		if entry.Revision() == 1 {
			return "create"
		}
		return "update"
	case jetstream.KeyValueDelete:
		return "delete"
	default:
		return "unknown"
	}
}

func (hb *HeartbeatService) Stop(ctx context.Context) error {
	if err := validateLifecycleContext(ctx, "HeartbeatService", "Stop"); err != nil {
		return err
	}
	hb.stopOnce.Do(func() {
		hb.logger.Info("Heartbeat service stopping")

		if hb.ticker != nil {
			hb.ticker.Stop()
		}

		// Signal the heartbeat loop to exit
		close(hb.stopChan)
	})
	baseErr := hb.BaseService.Stop(ctx)

	if hb.loopDone != nil {
		select {
		case <-hb.loopDone:
		case <-ctx.Done():
			return errors.Join(baseErr, fmt.Errorf("wait for heartbeat loop: %w", ctx.Err()))
		}
	}
	return baseErr
}

func (r *streamOverrideExpiryReporter) evaluate(now time.Time) {
	cfg := r.configOf()
	if cfg == nil {
		return
	}

	// Reset first so a bridge that was RENEWED or removed stops reporting. Without
	// this the gauge would latch at 1 forever and an operator who fixed the problem
	// would keep being paged for it.
	r.expired.Reset()
	for name, override := range cfg.StreamMigrationOverrides {
		r.expired.WithLabelValues(name, override.Owner).Set(0)
	}

	for _, lapsed := range config.ExpiredMigrationOverrides(cfg, now) {
		r.expired.WithLabelValues(lapsed.Stream, lapsed.Owner).Set(1)
		r.logger.Warn(
			"stream migration override has EXPIRED; the stream it admits is still unbounded and the next "+
				"boot will refuse to start",
			slog.String("stream", lapsed.Stream),
			slog.String("owner", lapsed.Owner),
			slog.String("expired", lapsed.Expires.Format(time.RFC3339)),
			slog.Duration("expired_ago", -lapsed.Remaining),
			slog.String("reason", lapsed.Reason),
			slog.String("remedy",
				"declare max_age, max_bytes and discard on the stream, or move it to archival_streams "+
					"(owner + reason) if permanence is genuinely its contract"),
		)
	}
}

func parseTripleQueryParams(r *http.Request) (tripleQueryParams, string) {
	q := r.URL.Query()

	p := tripleQueryParams{
		subject:   q.Get("subject"),
		predicate: q.Get("predicate"),
		object:    q.Get("object"),
		limit:     graphTriplesDefaultLimit,
	}

	if raw := q.Get("limit"); raw != "" {
		n, err := strconv.Atoi(raw)
		if err != nil {
			return tripleQueryParams{}, fmt.Sprintf("invalid limit %q: must be an integer", raw)
		}
		if n < 0 {
			return tripleQueryParams{}, fmt.Sprintf("invalid limit %d: must be non-negative", n)
		}
		if n == 0 {
			// limit=0 treated as "use default"
			n = graphTriplesDefaultLimit
		}
		if n > graphTriplesMaxLimit {
			n = graphTriplesMaxLimit
		}
		p.limit = n
	}

	return p, ""
}

