func (c ManagerConfig) Validate() error {
	if c.HTTPPort < 0 || c.HTTPPort > 65535 {
		return fmt.Errorf("invalid HTTP port: %d", c.HTTPPort)
	}
	if c.HTTPReadTimeout != "" {
		if _, err := time.ParseDuration(c.HTTPReadTimeout); err != nil {
			return fmt.Errorf("invalid http_read_timeout %q: %w", c.HTTPReadTimeout, err)
		}
	}
	if c.HTTPWriteTimeout != "" {
		if _, err := time.ParseDuration(c.HTTPWriteTimeout); err != nil {
			return fmt.Errorf("invalid http_write_timeout %q: %w", c.HTTPWriteTimeout, err)
		}
	}
	// SwaggerUI is a boolean (no validation needed)
	// ServerInfo fields can be empty (will get defaults)
	return nil
}

func (c HeartbeatConfig) Validate() error {
	if c.Interval == "" {
		return nil // Will use default
	}

	duration, err := time.ParseDuration(c.Interval)
	if err != nil {
		return fmt.Errorf("invalid interval: %w", err)
	}
	if duration <= 0 {
		return fmt.Errorf("invalid interval: must be positive")
	}
	if duration < time.Second {
		return fmt.Errorf("invalid interval: must be at least 1s")
	}

	return nil
}

func ConfigureRulePackMutations(manager *Manager) error {
	if manager == nil {
		return fmt.Errorf("rule-pack mutation composition requires a service manager")
	}
	plans, err := preflightRulePackMutations(manager)
	if err != nil {
		return err
	}
	for _, plan := range plans {
		if len(plan.contracts) == 0 {
			continue
		}
		client, err := projection.NewMutationClient(projection.MutationClientConfig{
			NATS: manager.natsClient, Contracts: plan.contracts,
		})
		if err != nil {
			return fmt.Errorf("build mutation client for rule pack %q: %w", plan.packID, err)
		}
		if err := plan.binder.SetPredicateReconciler(client); err != nil {
			return fmt.Errorf("inject predicate reconciler for rule pack %q: %w", plan.packID, err)
		}
	}
	return nil
}

